vertices = ["A", "B", "C", "D"]
edges = [("A", "B"), ("B", "C")]
graph = {}
for vertex in vertices:
    graph[vertex] = []
for source, target in edges:
    graph[source].append(target)
for vertex in graph:
    print(vertex, graph[vertex])

def directed_adj(vertices, edges):
    graph = {v: [] for v in vertices}
    for start, end in edges:
        graph[start].append(end)
    return graph

print(directed_adj(['A', 'B', 'C'], [('A', 'B')]))
print(directed_adj([], []))
print(directed_adj(['A'], [('A', 'A')]))

def weighted_matrix(vertices, edges):
    position = {v: i for i, v in enumerate(vertices)}
    matrix = [[None for _ in vertices] for _ in vertices]
    for start, end, cost in edges:
        matrix[position[start]][position[end]] = cost
    return matrix

print(weighted_matrix(['A', 'B'], [('A', 'B', 0)]))
print(weighted_matrix([], []))
print(weighted_matrix(['A'], [('A', 'A', 2)]))

def reverse_graph(graph):
    result = {v: [] for v in graph}
    for start, neighbors in graph.items():
        for end in neighbors:
            result[end].append(start)
    return result

print(reverse_graph({'A': ['B'], 'B': [], 'C': []}))
print(reverse_graph({}))
print(reverse_graph({'A': ['B', 'B'], 'B': ['A']}))

